import { existsSync } from 'node:fs'
import { spawnSync } from 'node:child_process'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

// one deploy path for onestack.dev: preflight credentials, then deploy the
// worker config generated by `bun run build:web` to the onestack-dev worker.
// used by .github/workflows/deploy-site.yml and by hand.

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const configPath = join(root, 'dist', 'worker', 'wrangler.json')

const generated = join('dist', 'worker', 'wrangler.json')
if (!existsSync(configPath)) {
  console.error(`missing ${generated}: run \`bun run build:web\` first`)
  process.exit(1)
}

// never default or skip these: a deploy without credentials must fail loudly
const missing = ['CLOUDFLARE_API_TOKEN', 'CLOUDFLARE_ACCOUNT_ID'].filter(
  (key) => !process.env[key]
)
if (missing.length > 0) {
  console.error(`missing Cloudflare credentials: ${missing.join(', ')}`)
  console.error(
    'set them as GitHub Actions secrets (CLOUDFLARE_API_TOKEN, CLOUDFLARE_ACCOUNT_ID) or export them locally'
  )
  process.exit(1)
}

// run the workspace-pinned wrangler through bun: --no-install resolves the
// installed 4.95.0 from node_modules and fails instead of fetching.
const result = spawnSync(
  process.execPath,
  ['x', '--no-install', 'wrangler', 'deploy', '--config', configPath],
  {
    cwd: root,
    stdio: 'inherit',
    env: process.env,
  }
)

if (result.error) {
  console.error(`failed to run wrangler: ${result.error.message}`)
  process.exit(1)
}
process.exit(result.status ?? 1)
